files.examples/01.js:
import { program } from "../data.grammar.js";

// The view (a 20-row grid) is rendering and is not in the language; .limit(20) is the table half of it.
// Column types cannot be inferred from the CSV, so they are declared.
export default ($) => program("first-look")
  .source("sales", { csv: "data/sales.csv", columns: { date: "date", region: "str", units: "f64", price: "f64" } })
  .table("head", "sales")
  .limit(20);

files.examples/02.js:
import { program } from "../data.grammar.js";

// The deliberate typo (row.revnue) is left out: the file must check clean.
export default ($) => program("clean-sales")
  .source("raw", { csv: "data/sales.csv", header: true, columns: { date: "date", region: "str", units: "f64", "Unit Price": "f64" } })
  .table("sales", "raw")
  .rename({ "Unit Price": "price" })
  .cast({ date: "date", units: "f64", price: "f64" })
  .trim("region")
  .replace("region", { "N.": "North", "S.": "South" })
  .dropNulls("date", "units")
  .dedupe("date", "region")
  .derive("revenue", (row) => row.units * row.price);

files.examples/03.js:
import { program } from "../data.grammar.js";

// REFUSED: partly. wb.select({ from: t => t.sales.distinct("region") }) is a build-time lambda (R8): the
// region param is a plain string here. wb.layout / wb.controls / .view are rendering (R8) and are omitted.
export default ($) => program("filters")
  .source("sales", { csv: "data/sales.csv", columns: { date: "date", region: "str", units: "f64", price: "f64" } })
  .param("minUnits", { min: 0, max: 500, step: 10, value: 50, label: "Minimum units" })
  .param("region", { value: "All" })
  .param("since", { value: "2026-01-01", type: "date" })
  .table("picked", "sales")
  .filter((row) => row.units >= $.minUnits)
  .filter((row) => $.region === "All" || row.region === $.region)
  .filter((row) => row.date >= $.since);

files.examples/04.js:
import { program } from "../data.grammar.js";

// REFUSED: partly. .y(() => $.metric) and .title(() => `...`) make a column name and text from a runtime
// param: a ref and a string are build-time values here, and there are no template literals. y is "revenue".
// The wb.layout / wb.controls view is rendering (R8) and is omitted.
export default ($) => program("revenue-by-month")
  .source("sales", { csv: "data/sales.csv", columns: { date: "date", region: "str", units: "f64", price: "f64" } })
  .param("metric", { options: ["revenue", "units"], value: "revenue" })
  .table("monthly", "sales")
  .derive("revenue", (row) => row.units * row.price)
